#include <bits/stdc++.h>

using namespace std;

typedef long long ll;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    function<ll(ll, ll)> power = [&](ll x, ll y) {
        if (y == 0) {
            return 1LL;
        }
        ll z = power(x, y / 2);
        return y % 2 == 0
            ? (z * z) % 998244353
            : ((z * z) % 998244353 * x) % 998244353;
    };

    unordered_map<ll, ll> divs;
    auto div = [&](ll x) {
        if (divs.find(x) != divs.end()) {
            return divs[x];
        }
        return divs[x] = power(x, 998244353 - 2);
    };

    ll n, m;
    cin >> n >> m;

    vector<bool> a(static_cast<size_t>(n));
    vector<ll> w(static_cast<size_t>(n));

    for (ll i = 0; i < n; i++) {
        ll v;
        cin >> v;
        a[i] = v == 1;
    }

    for (ll i = 0; i < n; i++) {
        cin >> w[i];
    }

    ll zeros = 0, ones = 0;
    for (ll i = 0; i < n; i++) {
        if (a[i]) {
            ones += w[i];
        } else {
            zeros += w[i];
        }
    }

    map<tuple<ll, ll>, ll> dp0;
    function<ll(ll, ll)> f0 = [&](ll z, ll o) {
        if (z - o <= zeros - ones - m) {
            return 1LL;
        }

        auto it = dp0.find({z, o});
        if (it != dp0.end()) {
            return it->second;
        }

        ll r = z * f0(z - 1, o) + (o + 1) * f0(z, o + 1);
        r %= 998244353;
        r *= div(z + o);
        r %= 998244353;
        return dp0[{z, o}] = r;
    };

    map<tuple<ll, ll>, ll> dp1;
    function<ll(ll, ll)> f1 = [&](ll z, ll o) {
        if (z - o <= zeros - ones - m) {
            return 1LL;
        }

        auto it = dp1.find({z, o});
        if (it != dp1.end()) {
            return it->second;
        }

        ll r = (z - 1) * f1(z - 1, o) + o * f1(z, o + 1);
        r %= 998244353;
        r *= div(z + o);
        r %= 998244353;
        return dp1[{z, o}] = r;
    };

    for (ll i = 0; i < n; i++) {
        if (a[i]) {
            cout << (f0(zeros, ones) * w[i]) % 998244353 << '\n';
        } else {
            cout << (f1(zeros, ones) * w[i]) % 998244353 << '\n';
        }
    }

    return 0;
}

