        if (y == 0) {
            return 1LL;
        }
        ll z = power(x, y / 2);
        return y % 2 == 0
                   ? (z * z) % MOD
                   : ((z * z) % MOD * x) % MOD;
    };

    unordered_map<ll, ll> divs;
    auto inverse = [&](ll x) -> ll {
        auto it = divs.find(x);
        if (it != divs.end()) {
            return it->second;
        }
        return divs[x] = power(x, MOD - 2);
    };

    ll n, m;
    cin >> n >> m;

    vector<bool> a(static_cast<size_t>(n));
    vector<ll> w(static_cast<size_t>(n));

    for (ll i = 0; i < n; i++) {
        ll v;
        cin >> v;
        a[i] = (v == 1);
    }

    for (ll i = 0; i < n; i++) {
        cin >> w[i];
    }

    ll zeros = 0, ones = 0;
    for (ll i = 0; i < n; i++) {
        if (a[i]) {
            ones += w[i];
        } else {
            zeros += w[i];
        }
    }

    map<tuple<ll, ll>, ll> dp0;
    function<ll(ll, ll)> f0 = [&](ll z, ll o) -> ll {
        if (z - o <= zeros - ones - m) {
            return 1LL;
        }

        auto key = make_tuple(z, o);
        auto it = dp0.find(key);
        if (it != dp0.end()) {
            return it->second;
        }

        ll r = (z * f0(z - 1, o) + (o + 1) * f0(z, o + 1)) % MOD;
        r = r * inverse(z + o) % MOD;
        return dp0[key] = r;
    };

    map<tuple<ll, ll>, ll> dp1;
    function<ll(ll, ll)> f1 = [&](ll z, ll o) -> ll {
        if (z - o <= zeros - ones - m) {
            return 1LL;
        }

        auto key = make_tuple(z, o);
        auto it = dp1.find(key);
        if (it != dp1.end()) {
            return it->second;
        }

        ll r = ((z - 1) * f1(z - 1, o) + o * f1(z, o + 1)) % MOD;
        r = r * inverse(z + o) % MOD;
        return dp1[key] = r;
    };

    for (ll i = 0; i < n; i++) {
        if (a[i]) {
            cout << f0(zeros, ones) * w[i] % MOD << '\n';
        } else {
            cout << f1(zeros, ones) * w[i] % MOD << '\n';
        }
    }

    return 0;
}

